{
  "verdict": "request_changes",
  "summary": "The implementation of `percent_of` fails to correctly round halves away from zero for negative values (refunds), violating both the rounding requirement and the symmetry requirement.",
  "findings": [
    {
      "finding_id": "rounding_error_negative_values",
      "file": "candidate.py",
      "line_start": 2,
      "line_end": 2,
      "severity": "high",
      "description": "The rounding logic `(amount_cents * percent + 50) // 100` only implements 'round half up' for positive numbers. For negative numbers, it fails to round halves away from zero, violating the requirement that `percent_of(-x, p) == -percent_of(x, p)`.",
      "evidence": "For `amount_cents = -5` and `percent = 10`, the expected result is `-1` (rounding -0.5 away from zero), but the candidate returns `0`."
    }
  ]
}
